'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isndarrayLike = require( '@stdlib/assert/is-ndarray-like' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var uniform = require( '@stdlib/random/uniform' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var splice = require( './../lib' );


// VARIABLES //

var types = [ 'float64' ];
var orders = [ 'row-major', 'column-major' ];


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {Array<PositiveInteger>} shape - ndarray shape
* @param {string} type - ndarray data type
* @param {string} order - memory layout
* @returns {Function} benchmark function
*/
function createBenchmark( shape, type, order ) {
	var arrays;
	var opts;
	var x;

	opts = {
		'dtype': type,
		'order': order
	};
	arrays = [
		uniform( [ shape[ 1 ], 1 ], 0.0, 100.0, opts ),
		uniform( [ shape[ 1 ], 1 ], 0.0, 100.0, opts ),
		uniform( [ shape[ 1 ], 1 ], 0.0, 100.0, opts )
	];
	x = uniform( shape, 0.0, 100.0, opts );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var out;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			out = splice( x, [ 1, 2, 6 ], [ arrays[ i%3 ], arrays[ (i+1)%3 ], arrays[ (i+2)%3 ] ] ); // eslint-disable-line max-len
			if ( typeof out !== 'object' ) {
				b.fail( 'should return an ndarray' );
			}
		}
		b.toc();
		if ( !isndarrayLike( out ) ) {
			b.fail( 'should return an ndarray' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var min;
	var max;
	var ord;
	var sh;
	var t1;
	var N;
	var f;
	var i;
	var j;
	var k;

	min = 2; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < orders.length; k++ ) {
		ord = orders[ k ];
		for ( j = 0; j < types.length; j++ ) {
			t1 = types[ j ];
			for ( i = min; i <= max; i++ ) {
				N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
				sh = [ N, N ];
				f = createBenchmark( sh, t1, ord );
				bench( format( '%s::equidimensional:size=%d,dim=-1,order=%s,num_slices=3,removed=3,inserted=3', pkg, N*N, ord ), f );
			}
		}
	}
}

main();
